// Kodein Landing Page Engine — Interactive Demonstrations
document.addEventListener('DOMContentLoaded', () => {
  initPricingToggle();
  initFaqAccordion();
  initPlaygroundSim();
});

// 1. Pricing Plan Switcher (Monthly vs Yearly with 20% discount)
function initPricingToggle() {
  const toggleBtn = document.getElementById('billingToggle');
  const pricePro = document.getElementById('pricePro');
  const priceTeam = document.getElementById('priceTeam');
  const periodPro = document.getElementById('periodPro');
  const periodTeam = document.getElementById('periodTeam');
  const badgeDiscount = document.getElementById('annualBadge');

  if (!toggleBtn) return;

  let isYearly = false;

  toggleBtn.addEventListener('click', () => {
    isYearly = !isYearly;

    // Toggle switch UI
    const dot = toggleBtn.querySelector('.toggle-dot');
    if (isYearly) {
      dot.classList.remove('translate-x-1');
      dot.classList.add('translate-x-7');
      toggleBtn.classList.replace('bg-slate-800', 'bg-cyan-500');

      // Update Price Texts with discount
      pricePro.textContent = 'Rp 79.000';
      priceTeam.textContent = 'Rp 299.000';
      periodPro.textContent = '/bln (ditagih tahunan)';
      periodTeam.textContent = '/bln (ditagih tahunan)';
      if (badgeDiscount) badgeDiscount.classList.remove('opacity-60');
      showToast('🎉 Diskon tahunan 20% diterapkan!');
    } else {
      dot.classList.remove('translate-x-7');
      dot.classList.add('translate-x-1');
      toggleBtn.classList.replace('bg-cyan-500', 'bg-slate-800');

      pricePro.textContent = 'Rp 99.000';
      priceTeam.textContent = 'Rp 375.000';
      periodPro.textContent = '/bulan';
      periodTeam.textContent = '/bulan';
      if (badgeDiscount) badgeDiscount.classList.add('opacity-60');
    }
  });
}

// 2. Interactive AI Playground Demo
const demoPresets = {
  card: {
    prompt: "Bikinkan kartu profil pengembang modern lengkap dengan badge dan status online.",
    code: `<!-- Output Kodein Sandbox -->\n<div class="p-4 bg-slate-900 border border-slate-800 rounded-2xl flex items-center gap-3.5 shadow-xl">\n  <div class="relative">\n    <img src="https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100" class="w-12 h-12 rounded-xl object-cover" />\n    <span class="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-500 border-2 border-slate-900 rounded-full"></span>\n  </div>\n  <div>\n    <h4 class="font-bold text-white text-sm">Sarah Alyssa</h4>\n    <p class="text-xs text-cyan-400">Full-Stack AI Engineer</p>\n  </div>\n</div>`,
    previewHtml: `
      <div class="p-5 bg-gradient-to-br from-slate-900 to-slate-950 border border-slate-800 rounded-2xl flex items-center justify-between shadow-2xl">
        <div class="flex items-center gap-3.5">
          <div class="relative">
            <div class="w-12 h-12 rounded-xl bg-cyan-500/20 text-cyan-300 font-bold flex items-center justify-center border border-cyan-500/30 text-lg">SA</div>
            <span class="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-400 border-2 border-slate-950 rounded-full animate-pulse"></span>
          </div>
          <div>
            <h4 class="font-bold text-white text-sm">Sarah Alyssa</h4>
            <p class="text-xs text-cyan-400 font-medium">Full-Stack AI Engineer</p>
          </div>
        </div>
        <span class="px-2.5 py-1 text-[11px] font-bold bg-cyan-500/10 text-cyan-300 rounded-lg border border-cyan-500/20">Aktif</span>
      </div>`
  },
