function initPlaygroundSim() {
  const promptInput = document.getElementById('playgroundPrompt');
  const codeOutput = document.getElementById('playgroundCode');
  const previewOutput = document.getElementById('playgroundPreview');
  const btnRun = document.getElementById('btnRunDemo');

  if (!promptInput || !codeOutput || !previewOutput) return;

  window.loadPreset = function(presetKey) {
    const data = demoPresets[presetKey];
    if (!data) return;

    promptInput.value = data.prompt;
    triggerSimulate(data);
  };

  if (btnRun) {
    btnRun.addEventListener('click', () => {
      triggerSimulate(demoPresets.card);
    });
  }

  function triggerSimulate(data) {
    codeOutput.textContent = "// 🤖 Alto sedang merancang komponen...";
    previewOutput.innerHTML = `
      <div class="flex flex-col items-center justify-center h-36 gap-2 text-slate-400">
        <svg class="w-6 h-6 animate-spin text-cyan-400" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path></svg>
        <span class="text-xs">Merender Live Preview...</span>
      </div>`;

    setTimeout(() => {
      codeOutput.textContent = data.code;
      previewOutput.innerHTML = data.previewHtml;
      showToast('Komponen berhasil dibuat dan di-render langsung!');
    }, 450);
  }
}

// 3. FAQ Accordion
function initFaqAccordion() {
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const header = item.querySelector('.faq-header');
    const answer = item.querySelector('.faq-answer');
    const icon = item.querySelector('.faq-icon');

    if (!header || !answer) return;

    header.addEventListener('click', () => {
      const isOpen = !answer.classList.contains('hidden');

      // Close others
      document.querySelectorAll('.faq-answer').forEach(ans => ans.classList.add('hidden'));
      document.querySelectorAll('.faq-icon').forEach(ic => ic.classList.remove('rotate-180'));

      if (!isOpen) {
        answer.classList.remove('hidden');
        if (icon) icon.classList.add('rotate-180');
      }
    });
  });
}

// 4. Modal Coba Gratis
window.openDemoModal = function() {
  const modal = document.getElementById('demoModal');
  if (modal) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
  }
};

window.closeDemoModal = function() {
  const modal = document.getElementById('demoModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  }
};

// 5. Lightweight Toast
function showToast(msg) {
  const toast = document.getElementById('liveToast');
  const toastText = document.getElementById('toastText');
  if (!toast || !toastText) return;

  toastText.textContent = msg;
  toast.classList.remove('translate-y-20', 'opacity-0', 'pointer-events-none');
  toast.classList.add('translate-y-0', 'opacity-100');

  setTimeout(() => {
    toast.classList.add('translate-y-20', 'opacity-0', 'pointer-events-none');
    toast.classList.remove('translate-y-0', 'opacity-100');
  }, 3200);
}
